function validate([n, edges, s, marked]) {
  if (!Number.isInteger(n) || n < 2 || n > 500) return 'n is between 2 and 500.';
  if (!Array.isArray(edges) || edges.length < 1 || edges.length > 10000) return 'edges needs 1 to 10^4 edges.';
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 3 || !edge.every(Number.isInteger)) return 'Each edge is [u, v, w] with integers.';
    const [u, v, w] = edge;
    if (u < 0 || u >= n || v < 0 || v >= n) return 'Edge endpoints must be nodes 0 to n - 1.';
    if (u === v) return 'An edge may not go from a node to itself.';
    if (w < 1 || w > 1000000) return 'Edge weights are between 1 and 10^6.';
  }
  if (!Number.isInteger(s) || s < 0 || s >= n) return 's must be a node from 0 to n - 1.';
  if (!Array.isArray(marked) || marked.length < 1 || marked.length > n - 1) return 'marked needs 1 to n - 1 nodes.';
  if (marked.some(v => !Number.isInteger(v) || v < 0 || v >= n)) return 'Marked nodes must be nodes 0 to n - 1.';
  if (marked.includes(s)) return 's cannot be marked.';
  if (new Set(marked).size !== marked.length) return 'marked may not list a node twice.';
  return null;
}

