function minimumDistance(n, edges, s, marked) {
  // Bellman-Ford: relax every edge n - 1 times, then look at the marked nodes.
  const dist = new Array(n).fill(Infinity);
  dist[s] = 0;
  for (let round = 1; round < n; round++)
    for (const [u, v, w] of edges) if (dist[u] + w < dist[v]) dist[v] = dist[u] + w;
  const best = Math.min(...marked.map(m => dist[m]));
  return best === Infinity ? -1 : best;
}

