function generate(rand, size) {
  const n = size === 'large' ? 500 : 2 + Math.floor(rand() * 6);
  const m = size === 'large' ? 2000 : 1 + Math.floor(rand() * 2 * n);
  const maxWeight = size === 'large' || rand() < 0.3 ? 1000000 : 5;
  const edges = [];
  for (let i = 0; i < m; i++) {
    const u = Math.floor(rand() * n);
    let v = Math.floor(rand() * (n - 1));
    if (v >= u) v++;
    edges.push([u, v, 1 + Math.floor(rand() * maxWeight)]);
  }
  const s = Math.floor(rand() * n);
  const others = [];
  for (let v = 0; v < n; v++) if (v !== s) others.push(v);
  for (let i = others.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [others[i], others[j]] = [others[j], others[i]];
  }
  const count = size === 'large' ? 1 + Math.floor(rand() * 5) : 1 + Math.floor(rand() * others.length);
  return [n, edges, s, others.slice(0, count)];
}
